for(let p=1;p<=5;p++){
 const byId=id=>telcPaperExercises.find(q=>q.id===`t${p}-${id}`);
 const second=byId('s2');second.cards=wordRounds[p-1];second.prompt='Ziehen Sie in jeder Runde eine Wortkarte. Stellen Sie eine Frage mit dem Wort zum Thema. Beantworten Sie danach die Frage einer anderen Person. Es gibt zwei Runden mit zwei Themen.';second.points=['Runde 1: eine Frage stellen und eine Frage beantworten','Runde 2: eine Frage stellen und eine Frage beantworten'];second.model=second.cards.map((c,i)=>`Runde ${i+1} (${c.theme}): ${c.model}`).join('\n');
 const third=byId('s3');third.cards=requestRounds[p-1].map(([picture,alt,model])=>({picture,alt,model}));third.prompt='Ziehen Sie zwei Bildkarten. Formulieren Sie zu jeder Karte eine höfliche Bitte. Reagieren Sie danach jeweils auf die Bitte einer anderen Person.';third.points=['Zwei Bitten formulieren','Auf zwei Bitten reagieren'];third.model=third.cards.map((c,i)=>`Runde ${i+1}: ${c.model}`).join('\n');third.explanation={en:'Use both picture cards. Make two requests and respond to two partner requests. These are original practice illustrations.',de:'Benutzen Sie beide Bildkarten. Formulieren Sie zwei Bitten und reagieren Sie auf zwei Bitten Ihres Partners. Die Bilder sind eigene Übungsillustrationen.'};
 const first=byId('s1');first.model=first.model.replace('Mein Familienname buchstabiere ich','Meinen Familiennamen buchstabiere ich');
 // Exactly numeric answers permit only formatting variants, not fuzzy digit matching.
 for(let n=1;n<=5;n++){const q=byId('f'+n);q.telcForm=true;q.numericAnswer=/^[\d +()-]+$/.test(q.answer);}
}
