const personalB='Liebe Mira,\nam Freitag habe ich Geburtstag. Die Feier ist aber erst am Samstag um 18 Uhr in meiner Wohnung. Bitte bring einen Salat mit. Getränke habe ich schon.\nViele Grüße\nLena';
const replacements=[['Tomas kommt am Samstag nach Nürnberg.',true],['Selin soll am Haupteingang warten.',true],['Tomas bleibt eine Woche.',false],['Lena feiert am Freitag.',false],['Mira soll einen Salat mitbringen.',true]];
replacements.forEach(([prompt,truth],i)=>Object.assign(telcPaperExercises.find(q=>q.id===`t5-l${i+1}`),{title:i<3?'Ein Besuch bei Selin':'Lenas Einladung',text:i<3?personalA:personalB,prompt,answer:truth?0:1,explanation:{en:i<3?'Check the arrival day, meeting point and return day in Tomas’s message.':'The birthday is Friday but the celebration is Saturday; Mira should bring salad.',de:i<3?'Prüfen Sie Anreisetag, Treffpunkt und Rückfahrt in Tomas’ Nachricht.':'Der Geburtstag ist Freitag, die Feier aber Samstag. Mira soll Salat mitbringen.'}}));


